{% extends "templates/print/ph_basis.html" %}
{% block titel %}Teilnehmerliste {{ doc.titel }}{% endblock %}
{% block kopfrechts %}{{ doc.titel }}<br>{{ ph_datum(doc.datum) }}{% if doc.uhrzeit_von %} · ab {{ doc.uhrzeit_von|string|truncate(5, True, '') }} Uhr{% endif %}<br>{{ _(doc.status) }}{% endblock %}
{% block inhalt %}
{% set rows = doc.anmeldungen|selectattr("status", "in", ["angemeldet", "bestaetigt", "erschienen"])|sort(attribute="name_person")|list %}
{% set warte = doc.anmeldungen|selectattr("status", "equalto", "warteliste")|list %}
{% set ns = namespace(personen=0) %}{% for a in rows %}{% set ns.personen = ns.personen + (a.personen or 1) %}{% endfor %}
<h1>Teilnehmerliste</h1>
<div class="ph-feld"><b>Ort</b> {{ doc.ort or "" }}</div>
<div class="ph-feld"><b>Anmeldungen</b> {{ rows|length }} · <b>Personen</b> {{ ns.personen }}{% if doc.kapazitaet %} von {{ doc.kapazitaet }} Plätzen{% endif %}</div>
<table class="ph-tabelle"><thead><tr><th style="width:6mm">#</th><th>Name</th><th class="zahl">Pers.</th><th>Telefon</th><th>Hinweis</th><th style="width:22mm">Erschienen</th></tr></thead><tbody>
{% for a in rows %}<tr><td>{{ loop.index }}</td><td>{{ a.name_person }}</td><td class="zahl">{{ a.personen or 1 }}</td><td>{{ a.telefon or "" }}</td><td>{{ a.nachricht or "" }}</td><td>&#9744;</td></tr>{% endfor %}
</tbody></table>
{% if warte %}<h2>Warteliste</h2><table class="ph-tabelle"><tbody>{% for a in warte %}<tr><td>{{ a.name_person }}</td><td class="zahl">{{ a.personen or 1 }}</td><td>{{ a.telefon or "" }}</td></tr>{% endfor %}</tbody></table>{% endif %}
<p class="ph-hinweis">Interner Ausdruck mit personenbezogenen Daten. Nach dem Abend vernichten; die Daten im System werden {{ doc.loeschfrist_monate or 3 }} Monate nach dem Event gelöscht.</p>
{% endblock %}

{% set rows = doc.anmeldungen|selectattr("status", "in", ["angemeldet", "bestaetigt", "erschienen"])|sort(attribute="name_person")|list %}
<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Namensschilder {{ doc.titel }}</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Bodoni+Moda:wght@400;500&family=Instrument+Sans:wght@400;500&display=swap">
<style>
body { margin: 0; font-family: "Instrument Sans", Arial, sans-serif; color: #30373e; }
.bogen { display: flex; flex-wrap: wrap; }
.schild { width: 85mm; height: 54mm; box-sizing: border-box; border: 0.3pt dashed #d9d4cc; padding: 6mm 7mm; display: flex; flex-direction: column; justify-content: space-between; page-break-inside: avoid; }
.marke { font-family: "Bodoni Moda", Georgia, serif; font-size: 10pt; letter-spacing: .18em; }
.name { font-family: "Bodoni Moda", Georgia, serif; font-size: 20pt; line-height: 1.15; }
.unten { font-size: 7.5pt; color: #6b7280; letter-spacing: .08em; text-transform: uppercase; }
</style></head><body>
<div class="bogen">
{% for a in rows %}{% for i in range(a.personen or 1) %}
<div class="schild"><div class="marke">PLATZHIRSCH</div><div class="name">{{ a.name_person }}{% if i > 0 %} <span style="font-size:11pt;color:#6b7280">+{{ i }}</span>{% endif %}</div><div class="unten">{{ doc.titel }} · {{ ph_datum(doc.datum) }}</div></div>
{% endfor %}{% endfor %}
</div></body></html>

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Einwilligungsnachweis {{ doc.email }}{% endblock %}
{% block kopfrechts %}Nachweis<br>{{ ph_datum(frappe.utils.nowdate()) }}{% endblock %}
{% block inhalt %}
<h1>Nachweis der Einwilligung</h1>
<div class="ph-feld"><b>E-Mail</b> {{ doc.email }}</div>
<div class="ph-feld"><b>Zweck</b> {{ doc.zweck }}</div>
<div class="ph-feld"><b>Status</b> {{ _(doc.status) }}</div>
<div class="ph-feld"><b>Erteilt am</b> {{ frappe.utils.format_datetime(doc.zeitpunkt, "dd.MM.yyyy HH:mm") }} ({{ doc.kanal }}{% if doc.quelle %}, {{ doc.quelle }}{% endif %})</div>
<div class="ph-feld"><b>Textversion</b> {{ doc.textversion }}</div>
{% if doc.doi_bestaetigt_am %}<div class="ph-feld"><b>Bestätigt am</b> {{ frappe.utils.format_datetime(doc.doi_bestaetigt_am, "dd.MM.yyyy HH:mm") }} über {{ doc.doi_bestaetigt_kanal or "–" }}</div>{% endif %}
{% if doc.widerrufen_am %}<div class="ph-feld"><b>Widerrufen am</b> {{ frappe.utils.format_datetime(doc.widerrufen_am, "dd.MM.yyyy HH:mm") }} über {{ doc.widerruf_kanal or "–" }}</div>{% endif %}
{% if doc.interessen %}<div class="ph-feld"><b>Interessen</b> {{ doc.interessen }}</div>{% endif %}
{% if doc.ip_hash %}<div class="ph-feld"><b>IP (Hash)</b> {{ doc.ip_hash }}</div>{% endif %}
<h2>Alle Einträge dieser Adresse</h2>
{% set alle = frappe.get_all("PH Einwilligung", filters={"email": doc.email}, fields=["zweck", "status", "zeitpunkt", "kanal", "textversion", "doi_bestaetigt_am", "widerrufen_am"], order_by="zeitpunkt desc") %}
<table class="ph-tabelle"><thead><tr><th>Zweck</th><th>Status</th><th>Erteilt</th><th>Kanal</th><th>Textversion</th><th>Bestätigt</th><th>Widerrufen</th></tr></thead><tbody>
{% for e in alle %}<tr><td>{{ e.zweck }}</td><td>{{ _(e.status) }}</td><td>{{ frappe.utils.format_datetime(e.zeitpunkt, "dd.MM.yyyy HH:mm") }}</td><td>{{ e.kanal }}</td><td>{{ e.textversion }}</td><td>{{ frappe.utils.format_datetime(e.doi_bestaetigt_am, "dd.MM.yyyy HH:mm") if e.doi_bestaetigt_am else "–" }}</td><td>{{ frappe.utils.format_datetime(e.widerrufen_am, "dd.MM.yyyy HH:mm") if e.widerrufen_am else "–" }}</td></tr>{% endfor %}
</tbody></table>
<p class="ph-hinweis">Nachweis nach Art. 7 Abs. 1 DSGVO. Der Wortlaut der Textversion liegt im Website-Repository (Formulare, consentCopy.js) und bei der Kanzlei.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Kampagnenbericht {{ doc.name }}{% endblock %}
{% block kopfrechts %}{{ doc.name }}<br>{{ ph_datum(doc.zeitraum_von) }}{% if doc.zeitraum_bis %} – {{ ph_datum(doc.zeitraum_bis) }}{% endif %}<br>{{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>{{ doc.titel }}</h1>
<div class="ph-feld"><b>Kanal</b> {{ doc.kanal }}</div>
<div class="ph-feld"><b>Ziel</b> {{ doc.ziel or "–" }}{% if doc.ziel_kennzahl %} ({{ doc.ziel_kennzahl }}: {{ doc.ziel_wert or "–" }}){% endif %}</div>
<div class="ph-feld"><b>UTM</b> {{ doc.utm_source or "–" }} / {{ doc.utm_medium or "–" }} / {{ doc.utm_campaign or "–" }}</div>
<h2>Kennzahlen</h2>
<table class="ph-tabelle"><tbody>
<tr><td>Budget</td><td class="zahl">{{ ph_betrag(doc.budget_cent) or "–" }}</td></tr>
<tr><td>Ausgaben</td><td class="zahl">{{ ph_betrag(doc.ausgaben_cent) }}</td></tr>
<tr><td>Impressionen / Klicks</td><td class="zahl">{{ doc.impressionen_gesamt or 0 }} / {{ doc.klicks_gesamt or 0 }} ({{ (doc.klickrate_promille or 0) / 10 }} %)</td></tr>
<tr><td>Anfragen</td><td class="zahl">{{ doc.anfragen_gesamt or 0 }}</td></tr>
<tr class="ph-summe"><td>Kosten je Anfrage</td><td class="zahl">{{ ph_betrag(doc.kosten_je_anfrage_cent) if doc.anfragen_gesamt else "–" }}</td></tr>
</tbody></table>
{% if doc.kennzahlen %}<h2>Verlauf</h2>
<table class="ph-tabelle"><thead><tr><th>Datum</th><th class="zahl">Impressionen</th><th class="zahl">Klicks</th><th class="zahl">Kosten</th><th>Notiz</th></tr></thead><tbody>
{% for z in doc.kennzahlen %}<tr><td>{{ ph_datum(z.datum) }}</td><td class="zahl">{{ z.impressionen or 0 }}</td><td class="zahl">{{ z.klicks or 0 }}</td><td class="zahl">{{ ph_betrag(z.kosten_cent) }}</td><td>{{ z.notiz or "" }}</td></tr>{% endfor %}
</tbody></table>{% endif %}
{% if doc.auswertung_notiz %}<h2>Fazit</h2><div>{{ doc.auswertung_notiz }}</div>{% endif %}
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Einlass {{ doc.titel }}{% endblock %}
{% block kopfrechts %}{{ doc.titel }}<br>{{ ph_datum(doc.datum) }}{% if doc.uhrzeit_von %} · ab {{ doc.uhrzeit_von|string|truncate(5, True, '') }} Uhr{% endif %}{% endblock %}
{% block inhalt %}
{% for a in doc.anmeldungen|selectattr("status", "in", ["angemeldet", "bestaetigt"])|sort(attribute="name_person") %}
<div class="ph-ticket">
  <div>{{ ph_event_ticket_qr(doc.name, a.name) }}</div>
  <div><h3>{{ a.name_person }}</h3>
  {{ a.personen or 1 }} {% if (a.personen or 1) == 1 %}Person{% else %}Personen{% endif %}{% if a.begleitung %} · {{ a.begleitung }}{% endif %}<br>
  <small>{{ doc.ort or "Showroom und Café, Landstraße 11, 6911 Lochau" }} · Code am Eingang scannen</small></div>
</div>
{% else %}<p>Keine angemeldeten Teilnehmer.</p>{% endfor %}
{% endblock %}
